diff --git a/src/greet.js b/src/greet.js
index bac4423..c20eab9 100644
--- a/src/greet.js
+++ b/src/greet.js
@@ -1,3 +1,7 @@
 export function greet(name) {
-  return `hello ${name}`;
+  const trimmed = typeof name === 'string' ? name.trim() : '';
+  if (trimmed === '') {
+    return 'hello there';
+  }
+  return `hello ${trimmed}`;
 }
diff --git a/test/greet.test.js b/test/greet.test.js
index 19efd74..8dcf444 100644
--- a/test/greet.test.js
+++ b/test/greet.test.js
@@ -5,3 +5,19 @@ import { greet } from '../src/greet.js';
 test('greets by name', () => {
   assert.equal(greet('world'), 'hello world');
 });
+
+test('greets generically when the name is empty', () => {
+  assert.equal(greet(''), 'hello there');
+});
+
+test('treats a whitespace-only name as empty', () => {
+  assert.equal(greet('   '), 'hello there');
+});
+
+test('greets generically when the name is missing', () => {
+  assert.equal(greet(), 'hello there');
+});
+
+test('trims surrounding whitespace from a name', () => {
+  assert.equal(greet('  world  '), 'hello world');
+});

